"""Write scope and reproduction notes for the currently retained uncertainty figures."""
import json
from pathlib import Path
import pandas as pd
from .paths import MOTIVATION

def write_notes():
 config=json.loads((MOTIVATION/'active-analysis.json').read_text())
 if config['cohort']=='frozen filtered CL3':
  from .notes_filtered import write_notes as write_filtered
  write_filtered(config);return
 ranking=pd.read_csv(MOTIVATION/'ranking-panel.csv');rmse=pd.read_csv(MOTIVATION/'rmse-panel.csv');decoding=pd.read_csv(MOTIVATION/'decoding-main-panel.csv')
 contact=ranking[ranking.descriptor=='b_contact_invd2'];error=rmse[rmse.descriptor=='b_contact_invd2'];fixed=config.get('contact_b_binning','').startswith('absolute_')
 n=int(decoding.n.iloc[0]);data=Path(config['ranking_statistics']).parent
 names=json.loads((MOTIVATION/'figure-manifest.json').read_text())['figures']
 titles={'uncertainty-bfactor-ecdf':'Contact-B cumulative distribution','uncertainty-a-decoding':'Representation decoding','uncertainty-b-affinity-ranking':'Affinity ranking by descriptor','uncertainty-b-affinity-rmse':'Affinity RMSE by descriptor','uncertainty-combined-contactb-combined':'Combined decoding + Contact-B ranking','uncertainty-contact-b-spearman-rmse':'Contact B factor: ranking and RMSE'}
 links=[f'- **{titles[name]}:** [PNG]({name}.png) · [PDF]({name}.pdf) · [SVG]({name}.svg)' for name in names if any((MOTIVATION/f'{name}.{ext}').exists() for ext in ['png','pdf','svg'])]
 scope=f'Current affinity figures use 1163 complexes. All five decoding models use the same {n} complete cases and identical nested 5×3 ridge folds; one alternate-location descriptor is missing. The frozen 733-case benchmark manifest and its original predictions remain unchanged.'
 ranges=', '.join(contact.group.astype(str));counts='/'.join(contact.n.astype(str))
 prefix=config.get('contact_b_prefix','fixed-contact-b')
 bins=(f'Contact B factor uses absolute ranges {ranges} Å², with counts {counts}. Finite middle ranges include the lower bound and exclude the upper bound. These exploratory user-requested ranges follow earlier tercile and absolute-bin analyses; they are not universal disorder categories. The open upper tail pools sparse high-B ranges. The cutoffs were specified during exploratory binning comparisons; no automated cutoff search was performed. Intervals are conditional on the selected cutoffs and do not account for this exploratory selection.' if fixed else 'Contact B factor uses equal-count terciles on the expanded cohort.')
 ylo,yhi=config.get('combined_right_ylim',[-.12,.24])
 geometry=f'The combined x-axis displays ranges only ({ranges}), with sample counts retained in the caption and table. The combined plot spans {ylo:.2f} to {yhi:.2f} in Spearman with 0.06-spaced ticks to retain all confidence intervals. Its dimensions are 15.8 × 3.42 inches; right-panel width is 3.132 inches. Axis titles and x category labels are 12.1 pt, y ticks 9 pt, left bar numbers 10.5 pt. Right markers have 8.8-pt diameter, white faces, blue edges, and appear in front of confidence intervals; data-line width is 6.5 pt and CI width 2.3 pt. The special black zero line is removed.'
 remaining='Normalized contact B factor, ligand RSCC, and protein RSCC use terciles with ties kept together. Alternate-location fraction uses zero / lower positive / higher positive groups, because most values are zero.'
 (MOTIVATION/'README.md').write_text('\n'.join(['# Current uncertainty figures','',scope,'',*links,'',bins,remaining,'','Positive ΔSpearman favors CoDE; negative ΔRMSE favors CoDE. The combined figure currently uses Spearman. Intervals are paired-complex bootstrap 95% intervals, not per-complex predictive uncertainty.','','Reproduce only the retained figures from saved statistics:','','```bash','cd figures && python -m _parts.fig_uncertainty.update_expanded --plots-only','```','','`figure-manifest.json` registers the retained stems. A stem whose PNG/PDF/SVG files have all been removed is skipped. Old figure commands route to this current analysis; removed combined/expanded layouts are not recreated. The combined filename is exactly `uncertainty-combined-contactb-combined`.','','[Caption and scope](caption-and-scope.md) · [Metric definitions](metric-definitions.md) · [Contact B factor and RMSE](combined-and-rmse.md) · [Coverage and expanded evaluation](expanded-cl3-evaluation.md).','']))
 rows=['| Contact B factor (Å²) | n | ΔSpearman [95% CI] | ΔRMSE [95% CI], pK |','|---|---:|---:|---:|']
 for a,b in zip(contact.itertuples(),error.itertuples()):rows.append(f'| {a.group} | {a.n} | {a.estimate:+.3f} [{a.ci_lo:+.3f}, {a.ci_hi:+.3f}] | {b.estimate:+.3f} [{b.ci_lo:+.3f}, {b.ci_hi:+.3f}] |')
 positive=', '.join(contact.loc[contact.ci_lo>0,'group'].astype(str)) or 'none'
 negative=', '.join(contact.loc[contact.ci_hi<0,'group'].astype(str)) or 'none'
 inconclusive=', '.join(contact.loc[(contact.ci_lo<=0)&(contact.ci_hi>=0),'group'].astype(str)) or 'none'
 interpretation=f'Positive pointwise ranking intervals: {positive}. Negative pointwise ranking intervals: {negative}. Intervals including zero: {inconclusive}. These results describe a B-dependent ranking pattern, not universal superiority, causal uncertainty use, or a general RMSE improvement. Finer-bin point estimates need not increase monotonically with B. B, protein family, crystallographic processing and affinity-label distributions can co-vary.'
 (MOTIVATION/'combined-and-rmse.md').write_text('\n'.join(['# Contact B factor: current combined and RMSE results','',scope,'',bins,'',*rows,'',interpretation,'',geometry,'','RMSE is computed separately for every model/seed within each bin, subtracting CoE from CoDE and averaging five differences. It is not RMSE of averaged predictions. All bins resample paired complexes for both models and all five fitted seeds in 8000 bootstrap replicates. Thresholds and fitted seeds are fixed. Intervals are pointwise and do not resample protein families or training seeds.','',f'Original expanded-cohort tercile tables remain in `../affinity/metric-review/ranking-by-metric-expanded-cl3/ranking-by-metric.csv` and `rmse-by-metric.csv`. Current absolute-B tables and memberships use the `{prefix}-*` prefix in that folder. The earlier 20/40-cut tables remain under `fixed-contact-b-*` without the cut suffix, and the 10/20/30-cut tables remain under `fixed-contact-b-10-20-30-*`. This retains earlier results alongside the requested alternative.','']))
 (MOTIVATION/'caption-and-scope.md').write_text('\n'.join(['# Current caption and interpretation','',scope,'',f'**Representation decoding.** Five models are evaluated on identical {n} complexes with five outer and three inner ridge-regression folds. Feature and target scaling are fit within training folds. Each target selects the ridge penalty by inner validation MSE. Bars show out-of-fold Spearman correlation; larger bars indicate greater descriptor recoverability, not greater uncertainty. These random-complex folds do not establish protein-family-disjoint generalization.','',f'**Affinity comparison.** Five fitted scalar MSE heads per model use the original 1559/410 train/validation split. Validation-selected epochs reproduce the original evaluation; original 733 test predictions agree within 1.91e-6. Only the held-out cohort is extended. {bins} {remaining}','',interpretation,'','**Protein RSCC.** The report-wide upper median is computed over amino-acid residue types only. All 1163 fetched validation reports have zero nucleotide RSCC entries; the protein-only values exactly equal the historical polymer values in this cohort. It is not a pocket-specific metric. Ligand RSCC uses the largest non-junk ligand residue type (≥6 atoms), best-RSCC copy; it does not guarantee an exact PDBbind ligand-instance match.','','**Model provenance.** CoE and CoDE use original EMA encoders with raw 640-D features. DeepDTA uses the existing validation-selected CPU CNN checkpoint; its 512-D drug/protein concatenation is affinity-supervised on the original training split. ProFSA uses uploaded frozen pretrained weights, with all 1163 vectors extracted in one float32 environment using the original data pipeline; five archived-feature checks differ by at most 0.066% in relative L2 due to numerical kernels. Nesso-1 uses public v1.0.0 without local fitting, with the same 384-D pooled final Pairformer blocks, five recycles and bf16 inference. † The manuscript flags Nesso affinity-pretraining overlap: it remains an additional reference with leakage. No baseline was selected using decoding scores.','','**Limits.** CoE and CoDE pretraining masking recipes differ. Current extension cases have not re-established every pretraining-overlap exclusion used in the manuscript. The frozen benchmark remains separate. Decoding is not a calibrated uncertainty estimate, and stratified correlations do not prove a causal uncertainty mechanism. Group differences require a contrast, not merely one interval excluding zero and another including it. Historical controls and literature records remain under their source folders; they are not regenerated by the current figure command.','']))
 missing=pd.read_csv(config['source']);missing=missing.loc[missing.occ_site_frac_altloc.isna(),'pid'].tolist()
 (MOTIVATION/'expanded-cl3-evaluation.md').write_text('\n'.join(['# Expanded CL3 evaluation','',scope,'','Raw LP-PDBBind CL3 test contains 1348 cases. The frozen filtered manifest contains 733. Of 492 additional cases with local density and structures, current official validation reports identify 430 passing the legacy ligand/polymer RSCC ≥0.8 checks. The other 185 cases have no local density (123), no ligand identified by the legacy parser (29), or fail RSCC thresholds (33). Missing historical local RSCC rows do not establish why those entries were excluded from the original manifest.','','All five models now cover the full 1163-case extension. Decoding uses 1162 complete cases; missing alternate-location value: '+', '.join(missing)+'.','',*rows,'','Absolute bins and earlier alternatives are retained for comparison. The ≥30 group pools the sparse higher-B ranges rather than excluding those complexes. Added cases have lower Contact B factor (median 12.57 versus 22.45 Å² in the frozen cohort). Cohort composition matters.','','[Feature sources, validation reports, per-seed predictions, coverage and numerical checks](../../../results/task1-affinity/_shared/260921_cl3_extension_cpu/README.md). Original 733-case source statistics remain under `../affinity/cl3-5seed/` and `../representation/`; current expanded statistics are in their separate `expanded-cl3` paths recorded in `active-analysis.json`.','']))
 (MOTIVATION/'metric-definitions.md').write_text('''# Definitions of the displayed descriptors

| Display label | Stored key | Definition and interpretation |
|---|---|---|
| Contact B factor | `b_contact_invd2` | Pocket protein heavy-atom B factors averaged with weights Σ over ligand heavy atoms of 1/max(distance,2 Å)². No hard distance cutoff. Higher B can reflect displacement/disorder and model/experimental effects; it is not a calibrated positional error. |
| Normalized contact B factor | `b_contact_invd2_z` | (Contact B factor − whole-protein mean B) / whole-protein B standard deviation (sample SD). Measures whether the interface has elevated B relative to its protein. |
| Ligand RSCC | `lig_rscc` | Legacy validation-report selector: largest non-junk ligand residue type with ≥6 atoms, best-RSCC copy. Lower values indicate weaker agreement of that fitted ligand with the density. Exact ligand-instance correspondence is not guaranteed. |
| Protein RSCC | `protein_rscc_median` | Upper median of report-wide amino-acid residue RSCC values. It is not restricted to the pocket. Lower values indicate weaker protein model–map agreement. No nucleotide RSCC entries occur in the audited 1163 reports, so these values equal the legacy `poc_rscc_median` values for this cohort. |
| Alternate-location fraction | `occ_site_frac_altloc` | Fraction of matched pocket heavy-atom sites within 4.5 Å of ligand heavy atoms having multiple records in the deposited mmCIF. Measures explicitly modeled alternate sites, not all possible conformations. It is omitted from the four-descriptor combined panel. |

B and alternate locations generally orient toward more modeled disorder/heterogeneity as they increase; RSCC orients toward weaker model–map support as it decreases. These descriptors overlap but measure different aspects and are not interchangeable estimates of predictive uncertainty.

The decoder also retains partial-occupancy fraction, pocket/protein B ratio, and crystallographic resolution in its eight-target statistics. All five models use the same complete-case set and nested ridge folds. See `caption-and-scope.md` for interpretation and model limitations.

The right combined plot uses absolute Contact-B intervals in Å². Other B-panel metrics retain terciles, while alternate locations use zero and two positive-value groups. The numerical thresholds and exact memberships are saved under `../affinity/metric-review/ranking-by-metric-expanded-cl3/`.
''')
